WITH latest_breadth AS (SELECT sector, pct_above_50dma FROM breadth.sector_daily WHERE snapshot_date = (SELECT MAX(snapshot_date) FROM breadth.sector_daily)),
latest_stage AS (SELECT sector, COUNT(*) AS stage2_count FROM scores.stage_snapshots WHERE snapshot_date = (SELECT MAX(snapshot_date) FROM scores.stage_snapshots) AND stage = 'STAGE_2' GROUP BY sector)
SELECT lb.sector, lb.pct_above_50dma, ls.stage2_count FROM latest_breadth lb JOIN latest_stage ls ON lb.sector = ls.sector ORDER BY ls.stage2_count DESC, lb.pct_above_50dma DESC LIMIT 10;

